import React, { useState } from 'react';

const Contact = () => {
  const [status, setStatus] = useState({ type: '', message: '' });

  const handleSubmit = async (e) => {
  e.preventDefault();
  setStatus({ type: '', message: '' });

  const formData = new FormData(e.target);  // Create FormData object with form data
  const API_URL = process.env.REACT_APP_API_URL;

  try {
    const res = await fetch(`${API_URL}/contact`, {
      method: 'POST',
      body: formData,
    });

    const data = await res.json();  // Parse the JSON response

    if (res.ok) {
      setStatus({ type: 'success', message: data.message ?? 'Message sent successfully!' });
      e.target.reset();  // Reset the form after successful submission
    } else {
      // Display error based on the data received
      console.error(data);
      setStatus({
        type: 'error',
        message: data.errors ? data.errors.join(', ') : 'Failed to send message.',
      });
    }
  } catch (err) {
    console.error('Submission Error:', err);  // Log the error for debugging
    setStatus({ type: 'error', message: 'An error occurred. Please try again.' });
  }
};


  return (
    <section id="contact">
      <h2 className="section-title">Contact Me</h2>
      <div className="contact-wrapper">
        {/* Contact Form */}
        <div className="contact-form">
          <form id="contact-form" onSubmit={handleSubmit}>
            <input type="text" name="name" placeholder="Your Name" required />
            <input type="email" name="email" placeholder="Your Email" required />
            <textarea name="message" placeholder="Your Message" rows="6" required></textarea>
            <button type="submit" className="btn-submit">Send Message</button>
          </form>

          {/* Status message (Success/Error) */}
          {status.message && (
            <div
              style={{
                color: status.type === 'success' ? 'green' : 'red',
                marginBottom: '10px',
              }}
            >
              {status.message}
            </div>
          )}
        </div>

        {/* Contact Info */}
        <div className="contact-info">
          <h3>Get in Touch</h3>
          <ul>
            <li>
              <strong>Email:</strong>
              <a href="mailto:devjangig@gmail.com">devjangig@gmail.com</a>
            </li>
            <li>
              <strong>Phone:</strong>
              <a href="tel:+911234567890">+91 1234567890</a>
            </li>
            <li>
              <strong>GitHub:</strong>
              <a href="https://github.com/dev9913" target="_blank" rel="noopener noreferrer">
                github.com/dev9913
              </a>
            </li>
            <li>
              <strong>LinkedIn:</strong>
              <a
                href="https://www.linkedin.com/in/dev-jangir-a7a8692b9"
                target="_blank"
                rel="noopener noreferrer"
              >
                linkedin.com/in/dev-jangir
              </a>
            </li>
          </ul>
        </div>
      </div>
    </section>
  );
};

export default Contact;
